/**
 * @description Single Scope Event Handler
 */
export class EventHandler {
    /**
     *
     * @param eventName Event Name
     * @description Single Scope Event Handler
     * @example
     * const eventHandler = new EventHandler("eventName");
     * eventHandler.on((arg1, arg2) => {
     *     console.log(arg1, arg2);
     * });
     * eventHandler.send("arg1", "arg2");
     */

    constructor(public eventName: string) {
        this.eventName = eventName;
    }

    public send(...args: any[]) {
        emit(this.eventName, ...args);
    }

    public on(callback: (...args: any[]) => void) {
        on(this.eventName, callback);
    }
}

/**
 * @description Multi Scope Event Handler
 */
export class NetEvent {
    /**
     *
     * @param eventName Event Name
     * @param target Target Player Server ID (Only used when sending data from the server to a client)
     * @description Multi Scope Event Handler
     * @example
     * // Server to Client
     *
     * // server.ts
     * const eventHandler = new NetEvent("eventName", 123); // 123 is the client's server ID
     * eventHandler.on((arg1, arg2) => {
     *     console.log(arg1, arg2);
     * });
     * eventHandler.send("arg1", "arg2");
     *
     * // client.ts
     * const eventHandler = new NetEvent("eventName"); // We did not specify a target because we're sending data to the server
     * eventHandler.on((arg1, arg2) => {
     *     console.log(arg1, arg2);
     * });
     * eventHandler.send("arg1", "arg2");
     */

    constructor(public eventName: string, public target?: number) {
        this.eventName = eventName;
        this.target = target || -1;
    }

    public send(...args: any[]) {
        emitNet(this.eventName, this.target, ...args);
    }

    public on(callback: (...args: any[]) => void) {
        onNet(this.eventName, callback);
    }
}
